Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -14,4 +14,29 @@
 <div class="mobile-controls hide" id="mobile"><div class="stick" id="stick"><div class="stick-knob" id="knob"></div></div><button class="super-btn" id="superBtn">SUPER</button><button class="fire-btn" id="fireBtn">ATTACK</button></div>
 <div class="panel" id="overlay"><section class="card"><div class="eyebrow">A MYTHIC 3V3 SHOWDOWN</div><h1>Legends clash.<br><em>Relics decide.</em></h1><p class="intro">Choose your champion, rally two allies, and seize the ancient relic. Hold the center until your team claims 100 points—or finish ahead when time runs out.</p><div class="roster"><div class="hero-chip teal"><span class="icon">🛡️</span><b>ATHENA</b><small>Greek · Vanguard</small></div><div class="hero-chip teal"><span class="icon">🕸️</span><b>ANANSI</b><small>Akan · Trickster</small></div><div class="hero-chip teal"><span class="icon">☀️</span><b>AMATERASU</b><small>Japanese · Sunblade</small></div><div class="hero-chip redteam"><span class="icon">🐍</span><b>LOKI</b><small>Norse · Shifter</small></div><div class="hero-chip redteam"><span class="icon">🦁</span><b>SEKHMET</b><small>Egyptian · Huntress</small></div><div class="hero-chip redteam"><span class="icon">🐉</span><b>QUETZAL</b><small>Aztec · Windcaller</small></div></div><div class="actions"><button class="start" id="startBtn">ENTER THE ARENA →</button><div class="hint"><span class="keys">W A S D</span> move · <span class="keys">CLICK</span> attack<br><span class="keys">SPACE</span> super · <span class="keys">SHIFT</span> dash</div></div></section></div>
 </main>
 <script>
+(()=>{
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');const W=1000,H=625;canvas.width=W;canvas.height=H;
+const $=id=>document.getElementById(id);let state='menu',last=0,elapsed=0,blue=0,red=0,shake=0,particles=[],shots=[],keys={},mouse={x:690,y:310,down:false},touch={x:0,y:0,active:false},lastDash=0,superCharge=0,notice='';
+const walls=[{x:0,y:0,w:1000,h:26},{x:0,y:599,w:1000,h:26},{x:0,y:0,w:26,h:625},{x:974,y:0,w:26,h:625}, {x:240,y:160,w:115,h:36},{x:645,y:160,w:115,h:36},{x:240,y:429,w:115,h:36},{x:645,y:429,w:115,h:36},{x:435,y:95,w:130,h:30},{x:435,y:500,w:130,h:30},{x:115,y:281,w:90,h:34},{x:795,y:310,w:90,h:34}];
+const heroData=[{name:'ATHENA',icon:'🛡️',color:'#69dfd1',hp:150,spd:155,range:225,damage:24,rate:.47},{name:'ANANSI',icon:'🕸️',color:'#ffc36c',hp:110,spd:180,range:210,damage:18,rate:.4},{name:'AMATERASU',icon:'☀️',color:'#fff08a',hp:125,spd:165,range:195,damage:23,rate:.52},{name:'LOKI',icon:'🐍',color:'#ff8279',hp:125,spd:172,range:205,damage:20,rate:.48},{name:'SEKHMET',icon:'🦁',color:'#ffae68',hp:150,spd:150,range:210,damage:24,rate:.55},{name:'QUETZAL',icon:'🐉',color:'#d99cff',hp:115,spd:168,range:235,damage:19,rate:.44}];
+function makeFighter(index,team,x,y,isPlayer=false){const d=heroData[index];return {index,team,x,y,vx:0,vy:0,r:17,hp:d.hp,max:d.hp,alive:true,respawn:0,fire:Math.random()*.8,super:0,dash:0,player:isPlayer,face:team?Math.PI:0,ai:Math.random()*2,kill:0};}
+let fighters=[];function reset(){elapsed=0;blue=red=0;shots=[];particles=[];superCharge=0;fighters=[makeFighter(0,0,165,310,true),makeFighter(1,0,210,245),makeFighter(2,0,210,390),makeFighter(3,1,835,310),makeFighter(4,1,790,245),makeFighter(5,1,790,390)];state='playing';$('overlay').classList.add('hide');$('matchHud').classList.remove('hide');$('objective').classList.remove('hide');$('tip').classList.remove('hide');$('mobile').classList.remove('hide');}
+function start(){reset();last=performance.now();requestAnimationFrame(loop)}$('startBtn').addEventListener('click',start);
+function clamp(v,a,b){return Math.max(a,Math.min(b,v))}function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}function norm(x,y){let l=Math.hypot(x,y)||1;return [x/l,y/l]}
+function wallHit(x,y,r){for(const b of walls){if(x+r>b.x&&x-r<b.x+b.w&&y+r>b.y&&y-r<b.y+b.h)return true}return false}
+function particle(x,y,color,n=6,speed=75){for(let i=0;i<n;i++){let a=Math.random()*6.283,v=20+Math.random()*speed;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:.3+Math.random()*.42,max:.72,color,r:2+Math.random()*3})}}
+function fire(f,target,superShot=false){if(!f.alive)return;let dx=target.x-f.x,dy=target.y-f.y,[nx,ny]=norm(dx,dy);f.face=Math.atan2(ny,nx);let d=heroData[f.index];if(!superShot&&f.fire>0)return;if(!superShot)f.fire=d.rate;let speed=superShot?340:360;shots.push({x:f.x+nx*22,y:f.y+ny*22,vx:nx*speed,vy:ny*speed,team:f.team,owner:f,life:superShot?.6:.75,damage:superShot?42:d.damage,r:superShot?12:7,super:superShot,color:f.team?'#ff8b79':d.color});particle(f.x+nx*19,f.y+ny*19,f.team?'#ff8b79':d.color,3,35)}
+function superMove(f){if(!f.alive)return;if(f.player){if(superCharge<100)return;superCharge=0;f.super=0;for(const e of fighters)if(e.team!==f.team&&e.alive&&dist(e,f)<112){e.hp-=45;let [nx,ny]=norm(e.x-f.x,e.y-f.y);e.vx+=nx*240;e.vy+=ny*240;particle(e.x,e.y,'#ffe27b',10,100)}particle(f.x,f.y,'#ffe27b',30,150);shake=8;notice='ATHENA’S AEGIS!';return;}else{if(f.super<100)return;f.super=0;let t=nearestEnemy(f);if(t){let [nx,ny]=norm(t.x-f.x,t.y-f.y);f.vx=nx*350;f.vy=ny*350;particle(f.x,f.y,heroData[f.index].color,12,100);for(const e of fighters)if(e.team!==f.team&&e.alive&&dist(e,f)<80)e.hp-=35;}}}
+function nearestEnemy(f){let enemies=fighters.filter(e=>e.team!==f.team&&e.alive);return enemies.sort((a,b)=>dist(f,a)-dist(f,b))[0]}
+function move(f,dx,dy,dt){let [nx,ny]=norm(dx,dy);let mag=Math.min(1,Math.hypot(dx,dy));let speed=heroData[f.index].spd*(f.dash>0?2.45:1);f.vx+=(nx*speed*mag-f.vx)*Math.min(1,dt*11);f.vy+=(ny*speed*mag-f.vy)*Math.min(1,dt*11);let x=f.x+f.vx*dt,y=f.y+f.vy*dt;if(!wallHit(x,f.y,f.r))f.x=x;else f.vx*=-.2;if(!wallHit(f.x,y,f.r))f.y=y;else f.vy*=-.2;f.x=clamp(f.x,45,955);f.y=clamp(f.y,45,580);}
+function update(dt){elapsed+=dt;let remaining=Math.max(0,120-elapsed);$('clock').textContent=`${Math.floor(remaining/60)}:${String(Math.ceil(remaining%60)).padStart(2,'0')}`;$('blueScore').textContent=Math.floor(blue);$('redScore').textContent=Math.floor(red);if(remaining===0||blue>=100||red>=100){state='over';resultScreen();return}
+ for(const f of fighters){if(!f.alive){f.respawn-=dt;if(f.respawn<=0){f.alive=true;f.hp=f.max;f.x=f.team?835:165;f.y=310+(Math.random()-.5)*95;particle(f.x,f.y,heroData[f.index].color,14,100)}continue}f.fire-=dt;f.dash=Math.max(0,f.dash-dt);f.super=Math.min(100,f.super);if(f.hp<f.max)f.hp=Math.min(f.max,f.hp+dt*2.7);
+ if(f.player){let dx=(keys.KeyD?1:0)-(keys.KeyA?1:0),dy=(keys.KeyS?1:0)-(keys.KeyW?1:0);if(touch.active){dx=touch.x;dy=touch.y}move(f,dx,dy,dt);let aim=mouse;let enemy=nearestEnemy(f);if(!mouse.moved&&enemy)aim=enemy;f.face=Math.atan2(aim.y-f.y,aim.x-f.x);if(mouse.down)fire(f,aim);}
+ else {let target=nearestEnemy(f);if(!target)continue;let d=dist(f,target),[nx,ny]=norm(target.x-f.x,target.y-f.y);let centerDist=Math.hypot(f.x-500,f.y-312);let mx=0,my=0;if(d>heroData[f.index].range*.73){mx=nx;my=ny}else if(d<80){mx=-nx;my=-ny}else{mx=-ny*.46;my=nx*.46}if(centerDist>135){let [cx,cy]=norm(500-f.x,312-f.y);mx+=cx*.7;my+=cy*.7}move(f,mx,my,dt);if(d<heroData[f.index].range+20)fire(f,target);if(f.super>=100&&d<125)superMove(f);}
+ }
+ // relic control captures when a team has more champions in its radius
+ let zone=fighters.filter(f=>f.alive&&Math.hypot(f.x-500,f.y-312)<92);let b=zone.filter(f=>!f.team).length,r=zone.filter(f=>f.team).length;if(b>r){blue+=dt*8;red=Math.max(0,red-dt*1.5)}else if(r>b){red+=dt*8;blue=Math.max(0,blue-dt*1.5)}
+ for(let i=shots.length-1;i>=0;i--){let s=shots[i];s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;if(s.life<=0||wallHit(s.x,s.y,s.r)){particle(s.x,s.y,s.color,3,25);shots.splice(i,1);continue}let hit=fighters.find(f=>f.alive&&f.team!==s.team&&dist(f,s)<f.r+s.r);if(hit){hit.hp-=s.damage;s.owner.super=Math.min(100,s.owner.super+11);if(s.owner.player)superCharge=Math.min(100,superCharge+13);hit.vx+=s.vx*.12;hit.vy+=s.vy*.12;particle(s.x,s.y,s.color,8,90);shake=2;shots.splice(i,1);if(hit.hp<=0){hit.alive=false;hit.respawn=3;hit.hp=0;s.owner.kill++;particle(hit.x,hit.y,heroData[hit.index].color,18,125);if(s.owner.player)superCharge=Math.min(100,superCharge+18)}}}
+ for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.96;p.vy*=.96;p.life-=dt;if(p.life<=0)particles.splice(i,1)}shake=Math.max(0,shake-dt*12);}
+function resultScreen(){ $('mobile').classList.add('hide');$('tip').classList.add('hide');$('objective').classList.add('hide');let won=blue>red;let card=$('overlay');card.classList.remove('hide');card.innerHTML=`<section class="card"><div class="eyebrow">${blue===red?'TIME IS UP':'THE RELIC HAS SPOKEN'}</div><h1>${blue===red?'A DRAW.':won?'SUN TEAM':'MOON TEAM'}<br><em>${blue===red?'Both sides stand tall.':won?'Victory!':'Claims the relic.'}</em></h1><p class="result">Final score <b class="blue">${Math.floor(blue)}</b> — <b class="red">${Math.floor(red)}</b>. ${won?'Athena and her allies have secured the ancient ground.':'The rival legends held the center this time.'}</p><div class="actions"><button class="start" id="again">FIGHT AGAIN ↻</button><div class="hint">Your team: <b>ATHENA · ANANSI · AMATERASU</b><br>Rivals: <b>LOKI · SEKHMET · QUETZAL</b></div></div></section>`;$('again').onclick=()=>{card.innerHTML=`<section class="card"><div class="eyebrow">A MYTHIC 3V3 SHOWDOWN</div><h1>Legends clash.<br><em>Relics decide.</em></h1><p class="intro">Take control of the ancient relic. Hold the center until your team claims 100 points—or finish ahead when time runs out.</p><div class="roster"><div class="hero-chip teal"><span class="icon">🛡️</span><b>ATHENA</b><small>Greek · Vanguard</small></div><div class="hero-chip teal"><span class="icon">🕸️</span><b>ANANSI</b><small>Akan · Trickster</small></div><div class="hero-chip teal"><span class="icon">☀️</span><b>AMATERASU</b><small>Japanese · Sunblade</small></div><div class="hero-chip redteam"><span class="icon">🐍</span><b>LOKI</b><small>Norse · Shifter</small></div><div class="hero-chip redteam"><span class="icon">🦁</span><b>SEKHMET</b><small>Egyptian · Huntress</small></div><div class="hero-chip redteam"><span class="icon">🐉</span><b>QUETZAL</b><small>Aztec · Windcaller</small></div></div><div class="actions"><button class="start" id="startBtn">ENTER THE ARENA →</button><div class="hint"><span class="keys">W A S D</span> move · <span class="keys">CLICK</span> attack<br><span class="keys">SPACE</span> super · <span class="keys">SHIFT</span> dash</div></div></section>`;$('startBtn').onclick=start;};}

