function draw(){ctx.save();if(shake){ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake)}ctx.clearRect(0,0,W,H);ctx.fillStyle='#426b57';ctx.fillRect(0,0,W,H);
 // arena turf
 for(let y=35;y<590;y+=42)for(let x=34;x<970;x+=48){ctx.fillStyle=((x/48|0)+(y/42|0))%2?'#47745c':'#4a785d';ctx.fillRect(x,y,46,40)}
 // paths and ornamental turf
 ctx.fillStyle='#9a895f';ctx.globalAlpha=.22;ctx.beginPath();ctx.ellipse(500,312,300,245,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
 // outer trim
 ctx.strokeStyle='#c9b57a';ctx.lineWidth=7;ctx.strokeRect(21,21,958,583);ctx.strokeStyle='#d5cc9b55';ctx.lineWidth=1;ctx.strokeRect(29,29,942,567);
 // decorative plants
 for(let i=0;i<36;i++){let x=(i*173+62)%930+35,y=(i*97+53)%520+48;if(walls.some(b=>x>b.x-12&&x<b.x+b.w+12&&y>b.y-12&&y<b.y+b.h+12)||Math.hypot(x-500,y-312)<130)continue;ctx.fillStyle=i%2?'#335f4b':'#59805a';ctx.beginPath();ctx.arc(x,y,7+(i%3)*2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#9eaa6688';ctx.beginPath();ctx.arc(x-2,y-2,2,0,Math.PI*2);ctx.fill()}
 // relic ring
 let pulse=1+Math.sin(performance.now()/270)*.045;ctx.save();ctx.translate(500,312);ctx.scale(pulse,pulse);ctx.fillStyle='#142c3177';ctx.beginPath();ctx.arc(0,0,101,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#f8d57a';ctx.lineWidth=3;ctx.setLineDash([9,7]);ctx.beginPath();ctx.arc(0,0,91,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);let zcol=blue>red?'#66e6d2':red>blue?'#ff837a':'#ffe19a';ctx.globalAlpha=.22;ctx.fillStyle=zcol;ctx.beginPath();ctx.arc(0,0,80,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.shadowColor=zcol;ctx.shadowBlur=22;ctx.fillStyle='#f5d875';ctx.beginPath();ctx.moveTo(0,-28);ctx.lineTo(22,-6);ctx.lineTo(15,21);ctx.lineTo(0,31);ctx.lineTo(-15,21);ctx.lineTo(-22,-6);ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#fff4bf';ctx.beginPath();ctx.arc(-5,-7,4,0,Math.PI*2);ctx.fill();ctx.restore();
 // rocks / cover
 for(const b of walls.slice(4)){ctx.fillStyle='#283f3d';ctx.beginPath();ctx.roundRect(b.x+3,b.y+7,b.w,b.h,10);ctx.fill();ctx.fillStyle='#8c8a67';ctx.strokeStyle='#c1b47d';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(b.x,b.y,b.w,b.h,9);ctx.fill();ctx.stroke();ctx.fillStyle='#beb486';ctx.globalAlpha=.5;ctx.fillRect(b.x+10,b.y+5,b.w-20,3);ctx.globalAlpha=1}
 for(const b of walls.slice(0,4)){ctx.fillStyle='#827a59';ctx.fillRect(b.x,b.y,b.w,b.h)}
 // shots
 for(const s of shots){ctx.shadowColor=s.color;ctx.shadowBlur=13;ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#fff8d8';ctx.beginPath();ctx.arc(s.x-s.r*.25,s.y-s.r*.25,s.r*.32,0,Math.PI*2);ctx.fill()}
 // fighters
 for(const f of fighters){if(!f.alive)continue;let d=heroData[f.index];ctx.save();ctx.translate(f.x,f.y);ctx.rotate(f.face);ctx.globalAlpha=.28;ctx.fillStyle='#101a1d';ctx.beginPath();ctx.ellipse(0,14,20,8,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle=f.team?'#ff8279':'#62decf';ctx.beginPath();ctx.arc(0,0,19,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fff4d9';ctx.lineWidth=f.player?3:2;ctx.stroke();ctx.fillStyle=f.team?'#792f38':'#1c6562';ctx.beginPath();ctx.arc(0,0,13,0,Math.PI*2);ctx.fill();ctx.font='17px serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(d.icon,0,1);ctx.fillStyle=f.team?'#ffe8da':'#dcfff4';ctx.beginPath();ctx.roundRect(11,-15,14,5,2);ctx.fill();ctx.restore();
 // health and nameplate
 ctx.fillStyle='#17211e';ctx.beginPath();ctx.roundRect(f.x-19,f.y-31,38,5,2);ctx.fill();ctx.fillStyle=f.team?'#ff796f':'#65e3ce';ctx.beginPath();ctx.roundRect(f.x-18,f.y-30,36*Math.max(0,f.hp/f.max),3,2);ctx.fill();if(f.player){ctx.fillStyle='#f5e7bb';ctx.font='bold 10px Outfit';ctx.textAlign='center';ctx.fillText('YOU · ATHENA',f.x,f.y-39)} }
 // particles
 for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
 // zone count and super meter
 if(state==='playing'){let inZone=fighters.filter(f=>f.alive&&Math.hypot(f.x-500,f.y-312)<92);let b=inZone.filter(f=>!f.team).length,r=inZone.length-b;ctx.fillStyle='#13202bd9';ctx.beginPath();ctx.roundRect(440,365,120,23,8);ctx.fill();ctx.font='bold 10px DM Mono';ctx.textAlign='center';ctx.fillStyle='#70ead7';ctx.fillText(`☀ ${b}`,468,380);ctx.fillStyle='#ff8378';ctx.fillText(`☾ ${r}`,531,380);let p=fighters[0];ctx.fillStyle='#121c25ba';ctx.beginPath();ctx.roundRect(20,565,180,38,10);ctx.fill();ctx.fillStyle='#a5b5b6';ctx.font='9px DM Mono';ctx.textAlign='left';ctx.fillText('ATHENA · AEGIS',31,578);ctx.fillStyle='#35464a';ctx.beginPath();ctx.roundRect(31,585,150,8,4);ctx.fill();ctx.fillStyle='#ffe27b';ctx.beginPath();ctx.roundRect(31,585,150*superCharge/100,8,4);ctx.fill();if(superCharge>=100){ctx.fillStyle='#fff3a1';ctx.font='bold 9px DM Mono';ctx.fillText('SPACE: READY!',31,600)}else{ctx.fillStyle='#c5d0ca';ctx.font='9px DM Mono';ctx.fillText(`${Math.floor(superCharge)}%`,187,592)} }
 ctx.restore();}
function loop(now){if(state!=='playing')return;let dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);draw();if(state==='playing')requestAnimationFrame(loop)}
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Space'){let p=fighters[0];if(p)superMove(p)}if(e.code==='ShiftLeft'||e.code==='ShiftRight'){let p=fighters[0];if(p&&state==='playing'&&performance.now()-lastDash>1100){p.dash=.22;lastDash=performance.now();particle(p.x,p.y,'#9bfff0',8,60)}}});window.addEventListener('keyup',e=>keys[e.code]=false);canvas.addEventListener('pointermove',e=>{let r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)*W/r.width;mouse.y=(e.clientY-r.top)*H/r.height;mouse.moved=true});canvas.addEventListener('pointerdown',e=>{if(e.target===canvas){mouse.down=true;canvas.setPointerCapture(e.pointerId)}});window.addEventListener('pointerup',()=>mouse.down=false);
const stick=$('stick'),knob=$('knob');stick.addEventListener('pointerdown',e=>{stick.setPointerCapture(e.pointerId);touch.active=true;stickMove(e)});stick.addEventListener('pointermove',e=>{if(touch.active)stickMove(e)});function stickMove(e){let r=stick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,l=Math.hypot(dx,dy),max=39;if(l>max){dx*=max/l;dy*=max/l}knob.style.transform=`translate(${dx}px,${dy}px)`;touch.x=dx/max;touch.y=dy/max}stick.addEventListener('pointerup',()=>{touch.active=false;touch.x=touch.y=0;knob.style.transform=''});$('fireBtn').addEventListener('pointerdown',e=>{e.preventDefault();mouse.down=true});$('fireBtn').addEventListener('pointerup',()=>mouse.down=false);$('superBtn').addEventListener('click',()=>superMove(fighters[0]));
// Menu backdrop is a rendered arena even before the match starts.
function menuDraw(){draw();if(state==='menu')requestAnimationFrame(menuDraw)}menuDraw();
})();
</script>

